package com.example.yuejie;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
/** Read-only paragraph comments. Endpoints, body digest and sort=0 verified independently. */
final class ParagraphCommentApi {
 final NovelApi api;final LocalLibrary library;final CommentStore cache;
 ParagraphCommentApi(Context c,LocalLibrary l){this(c,l,NovelApi::http);}
 ParagraphCommentApi(Context c,LocalLibrary l,NovelApi.Transport transport){api=new NovelApi(c,l,transport);library=l;cache=new CommentStore(c);}
 static String key(String kind,String book,String chapter,String version,String para,String cursor){return kind+":"+book+":"+chapter+":"+version+":"+para+":"+cursor;}
 JSONObject request(String path,JSONObject body)throws Exception{JSONObject p=api.profile("content");try{return request(path,body,p);}catch(NovelApi.EmptyResponse failure){if(!api.refreshContentProfile(p))throw failure;return request(path,body,api.profile("content"));}}
 JSONObject request(String path,JSONObject body,JSONObject p)throws Exception{
  Map<String,String> defaults=new HashMap<>();JSONArray a=p.getJSONArray("query_defaults");for(int i=0;i<a.length();i++){JSONArray v=a.getJSONArray(i);defaults.put(v.getString(0),v.getString(1));}
  String query="aid=1967&iid="+defaults.get("iid")+"&device_platform=android&compliance_status=0&device_id="+defaults.get("device_id");long ms=System.currentTimeMillis(),ts=ms/1000;Map<String,String> h=new HashMap<>();h.put("User-Agent","Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36");h.put("Accept-Encoding","gzip");h.put("X-Argus",ProtocolCrypto.argus(query,ts,ProtocolCrypto.RANDOM.nextInt(0x7fffffff),ProtocolCrypto.utf(body.toString())));h.put("X-Ladon",ProtocolCrypto.ladon(ts,ProtocolCrypto.random(4)));h.put("X-Helios",ProtocolCrypto.ladon(ts,ProtocolCrypto.random(4)));h.put("X-Khronos",Long.toString(ts));h.put("x-ss-req-ticket",Long.toString(ms));String raw=api.transport.request(NovelApi.BASE+path+"?"+query,h,body);if(raw==null||raw.trim().isEmpty())throw new NovelApi.EmptyResponse();JSONObject r=new JSONObject(raw);if(r.optInt("code",-1)!=0)throw new IOException("段评请求失败（"+r.optString("code")+"）");return r.getJSONObject("data");
 }
 JSONObject versions(String book,boolean force)throws Exception{String key=key("versions",book,"","","","");CommentStore.Entry old=cache.get(key);if(!force&&old!=null&&!old.stale)return old.value;JSONObject p=api.profile("content");List<String[]> pairs=api.contentPairs(p);pairs.add(new String[]{"book_id",book});pairs.add(new String[]{"book_type","0"});pairs.add(new String[]{"need_version","true"});JSONObject data=api.signed("/reading/bookapi/directory/all_items/v",pairs,p,null).getJSONObject("data"),out=new JSONObject();JSONArray items=data.getJSONArray("item_data_list");for(int i=0;i<items.length();i++){JSONObject x=items.getJSONObject(i);String v=x.optString("version");if(!v.isEmpty())out.put(x.getString("item_id"),v);}cache.put(key,out);return out;}
 JSONObject metadata(String book,String chapter)throws Exception{
  JSONObject existing=library.chapter(book,chapter);if(existing==null)throw new IOException("正文尚未加载");CommentStore.Entry cached=cache.get(key("mapping",book,chapter,"","",""));if(cached!=null&&!cached.stale&&cached.value.optString("text").equals(existing.optString("text")))return cached.value;
  JSONObject before=versions(book,true);String version=before.optString(chapter);if(version.isEmpty())throw new IOException("无法确认正文版本，暂不显示段评");JSONObject fresh=api.chapterRequest(book,chapter,api.profile("content"));String after=versions(book,true).optString(chapter);if(!version.equals(after))throw new IOException("正文版本已更新，请重试段评");if(!fresh.optBoolean("paragraph_mapping")||!existing.optString("text").equals(fresh.optString("text")))throw new IOException("正文已更新，请重新打开章节后查看段评");fresh.put("item_version",version);library.chapter(book,chapter,fresh);cache.put(key("mapping",book,chapter,"","",""),fresh);return fresh;
 }
 JSONObject stats(String book,String chapter,String version)throws Exception{JSONObject result=request("/novel/commentapi/idea/list/"+chapter+"/v1",new JSONObject().put("chapter_id",chapter).put("item_version",version));JSONObject raw=result.getJSONObject("data"),out=new JSONObject();Iterator<String> keys=raw.keys();while(keys.hasNext()){String k=keys.next();JSONObject v=raw.optJSONObject(k);if(k.matches("[0-9]+")&&v!=null)out.put(k,Math.max(0,v.optLong("count")));}cache.put(key("stats",book,chapter,version,"",""),out);return out;}
 static String secure(String url){return url.startsWith("http://")?"https://"+url.substring(7):url;}
 // The list summary may include paragraph terminators absent from extracted <p> text.
 // Preserve all other whitespace and characters so a different paragraph is still rejected.
 static boolean sameParagraph(String left,String right){return withoutTerminators(left).equals(withoutTerminators(right));}
 static String withoutTerminators(String text){int end=text.length();while(end>0&&(text.charAt(end-1)=='\n'||text.charAt(end-1)=='\r'))end--;return text.substring(0,end);}
 JSONObject comments(String book,String chapter,String version,String para,String cursor,String expected)throws Exception{
  int pid=Integer.parseInt(para);JSONObject business=new JSONObject().put("book_id",book).put("item_version",version).put("para_index",pid);JSONObject body=new JSONObject().put("business_param",business).put("chapter_id",chapter).put("comment_source",2).put("comment_type",1).put("count",20).put("group_type",15).put("sort",0);if(!cursor.isEmpty())body.put("cursor",cursor);
  JSONObject raw=request("/novel/commentapi/comment/list/"+chapter+"/v1",body),info=raw.getJSONObject("common_list_info");JSONArray data=raw.optJSONArray("data_list"),items=new JSONArray();String text=raw.optJSONObject("extra")==null?"":raw.getJSONObject("extra").optString("para_content");if(!text.isEmpty()&&!sameParagraph(text,expected))throw new IOException("段落内容与当前正文不一致，请刷新章节");
  if(data!=null)for(int i=0;i<data.length();i++){JSONObject comment=data.getJSONObject(i).getJSONObject("comment"),common=comment.getJSONObject("common"),expand=comment.getJSONObject("expand"),pos=expand.optJSONObject("comment_pos");if(!version.equals(expand.optString("item_version"))||!book.equals(expand.optString("book_id"))||!chapter.equals(common.optString("group_id"))||!sameParagraph(expected,expand.optString("para_src_content"))||pos==null||pos.optInt("start_para_index",-1)!=pid||pos.optInt("end_para_index",-1)!=pid)continue;
   JSONObject user=common.getJSONObject("user_info").getJSONObject("base_info"),content=common.getJSONObject("content"),stat=comment.optJSONObject("stat");JSONArray images=new JSONArray();JSONObject container=content.optJSONObject("image_data_list");JSONArray list=container==null?null:container.optJSONArray("image_data");if(list!=null)for(int j=0;j<list.length();j++){JSONObject image=list.getJSONObject(j);String url=secure(image.optString("web_uri"));if(url.startsWith("https://"))images.put(new JSONObject().put("url",url).put("width",image.optInt("width")).put("height",image.optInt("height")));}
   items.put(new JSONObject().put("id",comment.getString("comment_id")).put("name",user.optString("user_name","读者")).put("avatar",secure(user.optString("user_avatar"))).put("text",content.optString("text")).put("images",images).put("likes",stat==null?0:stat.optLong("digg_count")));
  }
  if(data!=null&&data.length()>0&&items.length()==0)throw new IOException("无法确认段评与正文对应关系");String next=info.optString("cursor");boolean more=info.optBoolean("has_more")&&!next.isEmpty()&&!next.equals(cursor);JSONObject page=new JSONObject().put("items",items).put("cursor",next).put("more",more).put("total",info.optLong("total"));cache.put(key("page",book,chapter,version,para,cursor),page);return page;
 }
}
